pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(uint256 seed, address caller) public {
        vm.assume(caller != address(0));
        vm.warp(seed);
        address ceo = c.ceoAddress();
        vm.prank(ceo);
        bool ok;
        try c.DrugDealer() { ok = true; } catch { ok = false; }
        assertTrue(ok && c.ceoAddress() == ceo);
    }
}
